'use strict';
const assert = require('node:assert');
const { ReplyTracker } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['ReplyTracker']);
const tracker = new ReplyTracker();
assert.deepStrictEqual(tracker.pending(), []);
assert.strictEqual(tracker.begin('a'), 'a');
assert.strictEqual(tracker.begin('b'), 'b');
assert.strictEqual(tracker.begin('c'), 'c');
assert.deepStrictEqual(tracker.pending(), ['a', 'b', 'c']);
assert.throws(() => tracker.begin('b'), RangeError);
assert.deepStrictEqual(tracker.pending(), ['a', 'b', 'c']);

const payload = { answer: 42 };
const resolved = tracker.resolve({ id: 'b', payload });
assert.deepStrictEqual(resolved, { id: 'b', payload });
assert.strictEqual(resolved.payload, payload);
assert.deepStrictEqual(tracker.pending(), ['a', 'c']);
assert.strictEqual(tracker.resolve({ id: 'missing', payload: 1 }), null);
assert.deepStrictEqual(tracker.pending(), ['a', 'c']);

const again = tracker.resolve({ id: 'a', payload: undefined });
assert.deepStrictEqual(again, { id: 'a', payload: undefined });
assert.ok(Object.hasOwn(again, 'payload'));
assert.deepStrictEqual(tracker.pending(), ['c']);
assert.notStrictEqual(again, tracker.resolve({ id: 'c', payload: undefined }));
assert.deepStrictEqual(tracker.pending(), []);
assert.strictEqual(tracker.resolve({ id: 'c', payload: 3 }), null);

tracker.begin('x');
const pendingCopy = tracker.pending();
pendingCopy.push('fake');
assert.deepStrictEqual(tracker.pending(), ['x']);
for (const bad of [undefined, null, '', 1]) {
  assert.throws(() => tracker.begin(bad), TypeError);
  assert.deepStrictEqual(tracker.pending(), ['x']);
}
for (const bad of [undefined, null, {}, { id: 'x' }, { id: '', payload: 1 }, { id: 'x', payload: 1, extra: true },
  Object.assign(Object.create({ inherited: true }), { id: 'x', payload: 1 })]) {
  assert.throws(() => tracker.resolve(bad), TypeError);
  assert.deepStrictEqual(tracker.pending(), ['x']);
}

